window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-839faae68dd8e39c"]={"versions": [{"id": "FIG-839faae68dd8e39c", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext der AUTOSAR Adaptive Platform (Software Architecture). Das Diagramm stellt die statische Architekturbeziehung zwischen einer Anwendungskomponente und dem Persistenz-Funktionscluster über eine native Programmierschnittstelle dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Adaptive Application</strong>: Komponente (UML Component), repräsentiert die anwendende Softwareeinheit.\n</li><li><strong>Persistency</strong> (<code>«aapFunctionalCluster»</code>): Plattform-Komponente / Functional Cluster der AUTOSAR Adaptive Platform zur Verwaltung persistenter Daten.\n</li><li><strong>Persistency</strong> (<code>«aapAPI,aapNativeInterface»</code>): Klassifiziertes Schnittstellenelement, implementiert vom Functional Cluster <code>Persistency</code> (Realisierungsbeziehung, gestrichelte Linie mit geschlossener, nicht ausgefüllter Pfeilspitze) und genutzt von <code>Adaptive Application</code> (Abhängigkeit <code>«use»</code>, gestrichelte Pfeillinie).\n<ul class=\"fig-list\"><li>Enthaltene Operationen:\n<ul class=\"fig-list\"><li><code>+ RegisterApplicationDataUpdateCallback()</code>\n</li><li><code>+ RegisterRecoveryReportCallback()</code>\n</li><li><code>+ ResetPersistency()</code>\n</li><li><code>+ UpdatePersistency()</code>\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schnittstellendefinition und Verwendungsbeziehung. Die <code>Adaptive Application</code> greift über synchrone bzw. asynchrone Funktionsaufrufe der nativen Schnittstelle <code>Persistency</code> auf zentrale Verwaltungsfunktionen der Persistenz zu:</p>\n<ul class=\"fig-list\"><li>Registrierung einer anwendungsspezifischen Aktualisierungs-Callback-Funktion (<code>RegisterApplicationDataUpdateCallback</code>).\n</li><li>Registrierung einer Callback-Funktion zur Meldung von Wiederherstellungsereignissen (<code>RegisterRecoveryReportCallback</code>).\n</li><li>Vollständiges Zurücksetzen persistierter Daten (<code>ResetPersistency</code>).\n</li><li>Aktualisieren persistenter Speicherbereiche nach der Installation neuer Manifeste (<code>UpdatePersistency</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturvorgabe für AUTOSAR AP-konforme Implementierungen des Functional Clusters <code>Persistency</code>:</p>\n<ul class=\"fig-list\"><li>Bereitstellung einer nativen C++-Programmierschnittstelle für allgemeine Persistenz-Verwaltungsaufgaben.\n</li><li>Trennung von plattforminterner Realisierung (<code>«aapFunctionalCluster»</code>) und öffentlicher Anwendungs-API (<code>«aapAPI,aapNativeInterface»</code>).\n</li><li>Entwickler von Adaptive Applications müssen Callback-Mechanismen für Update- und Recovery-Prozesse über diese Standardoperationen anbinden und die Lebenszyklus-Operationen (<code>ResetPersistency</code>, <code>UpdatePersistency</code>) gemäß Plattform-Vorgaben steuern.\n</li></ul>"}, {"id": "FIG-dfc5466632b0ca5e", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext der AUTOSAR Adaptive Platform (Software Architecture). Das Diagramm stellt die statische Architekturbeziehung zwischen einer Anwendungskomponente und dem Persistenz-Funktionscluster über eine native Programmierschnittstelle dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Adaptive Application</strong>: Komponente (UML Component), repräsentiert die anwendende Softwareeinheit.\n</li><li><strong>Persistency</strong> (<code>«aapFunctionalCluster»</code>): Plattform-Komponente / Functional Cluster der AUTOSAR Adaptive Platform zur Verwaltung persistenter Daten.\n</li><li><strong>Persistency</strong> (<code>«aapAPI,aapNativeInterface»</code>): Klassifiziertes Schnittstellenelement, implementiert vom Functional Cluster <code>Persistency</code> (Realisierungsbeziehung, gestrichelte Linie mit geschlossener, nicht ausgefüllter Pfeilspitze) und genutzt von <code>Adaptive Application</code> (Abhängigkeit <code>«use»</code>, gestrichelte Pfeillinie).\n<ul class=\"fig-list\"><li>Enthaltene Operationen:\n<ul class=\"fig-list\"><li><code>+ RegisterApplicationDataUpdateCallback()</code>\n</li><li><code>+ RegisterRecoveryReportCallback()</code>\n</li><li><code>+ ResetPersistency()</code>\n</li><li><code>+ UpdatePersistency()</code>\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schnittstellendefinition und Verwendungsbeziehung. Die <code>Adaptive Application</code> greift über synchrone bzw. asynchrone Funktionsaufrufe der nativen Schnittstelle <code>Persistency</code> auf zentrale Verwaltungsfunktionen der Persistenz zu:</p>\n<ul class=\"fig-list\"><li>Registrierung einer anwendungsspezifischen Aktualisierungs-Callback-Funktion (<code>RegisterApplicationDataUpdateCallback</code>).\n</li><li>Registrierung einer Callback-Funktion zur Meldung von Wiederherstellungsereignissen (<code>RegisterRecoveryReportCallback</code>).\n</li><li>Vollständiges Zurücksetzen persistierter Daten (<code>ResetPersistency</code>).\n</li><li>Aktualisieren persistenter Speicherbereiche nach der Installation neuer Manifeste (<code>UpdatePersistency</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturvorgabe für AUTOSAR AP-konforme Implementierungen des Functional Clusters <code>Persistency</code>:</p>\n<ul class=\"fig-list\"><li>Bereitstellung einer nativen C++-Programmierschnittstelle für allgemeine Persistenz-Verwaltungsaufgaben.\n</li><li>Trennung von plattforminterner Realisierung (<code>«aapFunctionalCluster»</code>) und öffentlicher Anwendungs-API (<code>«aapAPI,aapNativeInterface»</code>).\n</li><li>Entwickler von Adaptive Applications müssen Callback-Mechanismen für Update- und Recovery-Prozesse über diese Standardoperationen anbinden und die Lebenszyklus-Operationen (<code>ResetPersistency</code>, <code>UpdatePersistency</code>) gemäß Plattform-Vorgaben steuern.\n</li></ul>"}, {"id": "FIG-1f0c8ae68a0e7b13", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext der AUTOSAR Adaptive Platform (Software Architecture). Das Diagramm stellt die statische Architekturbeziehung zwischen einer Anwendungskomponente und dem Persistenz-Funktionscluster über eine native Programmierschnittstelle dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Adaptive Application</strong>: Komponente (UML Component), repräsentiert die anwendende Softwareeinheit.\n</li><li><strong>Persistency</strong> (<code>«aapFunctionalCluster»</code>): Plattform-Komponente / Functional Cluster der AUTOSAR Adaptive Platform zur Verwaltung persistenter Daten.\n</li><li><strong>Persistency</strong> (<code>«aapAPI,aapNativeInterface»</code>): Klassifiziertes Schnittstellenelement, realisiert vom Functional Cluster <code>Persistency</code> (Realisierungsbeziehung, gestrichelte Linie mit geschlossener, nicht ausgefüllter Pfeilspitze) und genutzt von <code>Adaptive Application</code> (Abhängigkeit <code>«use»</code>, gestrichelte Pfeillinie).\n<ul class=\"fig-list\"><li>Enthaltene Operation:\n<ul class=\"fig-list\"><li><code>+ RegisterRecoveryReportCallback()</code>\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schnittstellendefinition und Verwendungsbeziehung. Die <code>Adaptive Application</code> greift über die native Schnittstelle <code>Persistency</code> auf die Registrierung einer Callback-Funktion zu:</p>\n<ul class=\"fig-list\"><li>Registrierung einer Meldefunktion zur Berichterstattung über Wiederherstellungsvorgänge (<code>RegisterRecoveryReportCallback</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturvorgabe für AUTOSAR AP-konforme Implementierungen des Functional Clusters <code>Persistency</code>:</p>\n<ul class=\"fig-list\"><li>Bereitstellung einer nativen Programmierschnittstelle für die Registrierung von Wiederherstellungs-Callbacks.\n</li><li>Trennung von plattforminterner Realisierung (<code>«aapFunctionalCluster»</code>) und anwendungsseitiger API-Nutzung (<code>«aapAPI,aapNativeInterface»</code>).\n</li><li>Anwendungsentwickler nutzen die allgemeine Persistenz-Schnittstelle ausschließlich zur Registrierung des Recovery-Report-Callbacks.\n</li></ul>"}, {"id": "FIG-7dc27fc2296ac0a1", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext der AUTOSAR Adaptive Platform (Software Architecture). Das Diagramm stellt die statische Architekturbeziehung zwischen einer Anwendungskomponente und dem Persistenz-Funktionscluster über eine native Programmierschnittstelle dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Adaptive Application</strong>: Komponente (UML Component), repräsentiert die anwendende Softwareeinheit.\n</li><li><strong>Persistency</strong> (<code>«aapFunctionalCluster»</code>): Plattform-Komponente / Functional Cluster der AUTOSAR Adaptive Platform zur Verwaltung persistenter Daten.\n</li><li><strong>Persistency</strong> (<code>«aapAPI,aapNativeInterface»</code>): Klassifiziertes Schnittstellenelement, realisiert vom Functional Cluster <code>Persistency</code> (Realisierungsbeziehung, gestrichelte Linie mit geschlossener, nicht ausgefüllter Pfeilspitze) und genutzt von <code>Adaptive Application</code> (Abhängigkeit <code>«use»</code>, gestrichelte Pfeillinie).\n<ul class=\"fig-list\"><li>Enthaltene Operation:\n<ul class=\"fig-list\"><li><code>+ RegisterRecoveryReportCallback()</code>\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schnittstellendefinition und Verwendungsbeziehung. Die <code>Adaptive Application</code> greift über die native Schnittstelle <code>Persistency</code> auf die Registrierung einer Callback-Funktion zu:</p>\n<ul class=\"fig-list\"><li>Registrierung einer Meldefunktion zur Berichterstattung über Wiederherstellungsvorgänge (<code>RegisterRecoveryReportCallback</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturvorgabe für AUTOSAR AP-konforme Implementierungen des Functional Clusters <code>Persistency</code>:</p>\n<ul class=\"fig-list\"><li>Bereitstellung einer nativen Programmierschnittstelle für die Registrierung von Wiederherstellungs-Callbacks.\n</li><li>Trennung von plattforminterner Realisierung (<code>«aapFunctionalCluster»</code>) und anwendungsseitiger API-Nutzung (<code>«aapAPI,aapNativeInterface»</code>).\n</li><li>Anwendungsentwickler nutzen die allgemeine Persistenz-Schnittstelle ausschließlich zur Registrierung des Recovery-Report-Callbacks.\n</li></ul>"}, {"id": "FIG-53848449fb9e0668", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext der AUTOSAR Adaptive Platform (Software Architecture). Das Diagramm stellt die statische Architekturbeziehung zwischen einer Anwendungskomponente und dem Persistenz-Funktionscluster über eine native Programmierschnittstelle dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Adaptive Application</strong>: Komponente (UML Component), repräsentiert die anwendende Softwareeinheit.\n</li><li><strong>Persistency</strong> (<code>«aapFunctionalCluster»</code>): Plattform-Komponente / Functional Cluster der AUTOSAR Adaptive Platform zur Verwaltung persistenter Daten.\n</li><li><strong>Persistency</strong> (<code>«aapAPI,aapNativeInterface»</code>): Klassifiziertes Schnittstellenelement, realisiert vom Functional Cluster <code>Persistency</code> (Realisierungsbeziehung, gestrichelte Linie mit geschlossener, nicht ausgefüllter Pfeilspitze) und genutzt von <code>Adaptive Application</code> (Abhängigkeit <code>«use»</code>, gestrichelte Pfeillinie).\n<ul class=\"fig-list\"><li>Enthaltene Operation:\n<ul class=\"fig-list\"><li><code>+ RegisterRecoveryReportCallback()</code>\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schnittstellendefinition und Verwendungsbeziehung. Die <code>Adaptive Application</code> greift über die native Schnittstelle <code>Persistency</code> auf die Registrierung einer Callback-Funktion zu:</p>\n<ul class=\"fig-list\"><li>Registrierung einer Meldefunktion zur Berichterstattung über Wiederherstellungsvorgänge (<code>RegisterRecoveryReportCallback</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturvorgabe für AUTOSAR AP-konforme Implementierungen des Functional Clusters <code>Persistency</code>:</p>\n<ul class=\"fig-list\"><li>Bereitstellung einer nativen Programmierschnittstelle für die Registrierung von Wiederherstellungs-Callbacks.\n</li><li>Trennung von plattforminterner Realisierung (<code>«aapFunctionalCluster»</code>) und anwendungsseitiger API-Nutzung (<code>«aapAPI,aapNativeInterface»</code>).\n</li><li>Anwendungsentwickler nutzen die allgemeine Persistenz-Schnittstelle ausschließlich zur Registrierung des Recovery-Report-Callbacks.\n</li></ul>"}], "trans": [{"from": "FIG-839faae68dd8e39c", "to": "FIG-dfc5466632b0ca5e", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-dfc5466632b0ca5e", "to": "FIG-1f0c8ae68a0e7b13", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Operation <code>RegisterApplicationDataUpdateCallback()</code> an Schnittstelle <code>Persistency</code> entfernt.\n</li><li>Operation <code>ResetPersistency()</code> an Schnittstelle <code>Persistency</code> entfernt.\n</li><li>Operation <code>UpdatePersistency()</code> an Schnittstelle <code>Persistency</code> entfernt.\n</li></ul>"}, {"from": "FIG-1f0c8ae68a0e7b13", "to": "FIG-7dc27fc2296ac0a1", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7dc27fc2296ac0a1", "to": "FIG-53848449fb9e0668", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
